  const list = (Array.isArray(rows) ? rows : rows ? [rows] : []).filter((r) => r && s(r.id));
  const byId = {};
  for (const r of list) byId[s(r.id)] = r;
  const jobs = ((plan && plan.items) || []).map((it) => {
    const j = byId[it.jobId] || null;
    return { job_id: it.jobId, before: it.jobStatus, job_status: j ? s(j.job_status) : "", error_code: j ? s(j.error_code) : "", ida_id: j ? s(j.ida_id) : "", attempt_count: j ? s(j.attempt_count) : "" };
  });
  const first = jobs[0] || null;
  const firstRow = first ? byId[first.job_id] || null : null;
  return { worker_route: guard.route === "REJECT" ? "REJECTED" : !plan || plan.route === "IDLE" ? "IDLE" : "WORKED", processed: String(jobs.length), jobs: JSON.stringify(jobs), job_id: first ? first.job_id : "", job_status: first ? first.job_status : "", result_code: firstRow && s(firstRow.error_code) ? s(firstRow.error_code) : s(guard.result_code), result_message: firstRow && s(firstRow.error_message) ? s(firstRow.error_message) : s(guard.result_message) || s(plan && plan.result_message), ida_id: first ? first.ida_id : "", evidence: JSON.stringify({ v: 1, workflow: "IDA_V2_WORKER", path: "REJECTED_INPUT" }) };
};
const guard = [{{node:code_node_DWguard.data}}][0];
const plan = null;
const res = workerResult(guard, plan, []);
console.log("worker result", JSON.stringify({ route: res.worker_route, processed: res.processed }));
