  return { jobId: s(row.id), organizationId: s(row.organization_id), idaId: s(row.ida_id), prevStatus: s(row.prev_status), jobStatus: s(row.job_status), progressPercent: Number(row.progress_percent) || 0, progressMessage: s(row.progress_message), attempts: Number(row.attempt_count) || 0, nextAttemptAt: row.next_attempt_at || null, leaseOwner: row.lease_owner || null, leaseExpiresAt: row.lease_expires_at || null, deadLease: dead ? "YES" : "NO", deadOwner: dead ? s(row.lease_owner) : "", deadClaim: claimed && String(row.claim_live) !== "1" ? "YES" : "NO", claimOwner: claimed ? s(row.claim_owner) : "", rowVersion: Number(row.row_version) || 0, errorCode: row.error_code || null, errorMessage: row.error_message || null, errorDetails: row.error_details || null, leaseLive: String(row.lease_live) === "1" ? "YES" : "NO", dueNow: String(row.due_now) === "1" ? "YES" : "NO", gateClosed: String(row.claim_live) === "1" ? "a live worker claim row W0_CLAIM_" + s(row.row_version) + " of " + s(row.claim_owner) : "" };
